<script>document.addEventListener('click',function(event){const button=event.target.closest('.js-swal-delete, button[onclick*="confirm"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const legacyMessage=(button.getAttribute('onclick')||'').match(/confirm\('([^']+)'\)/);Swal.fire({icon:'warning',title:'Hapus data?',text:button.dataset.message||(legacyMessage?legacyMessage[1]:'Data yang dihapus tidak dapat dikembalikan.'),showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal',confirmButtonColor:'#dc3545'}).then(result=>{if(result.isConfirmed)button.closest('form').submit()})},true)</script>
